USE retail_dw;

-- -------------------------------------------------------------
-- staging_sales  (9993 rows)
-- -------------------------------------------------------------




















-- -------------------------------------------------------------
-- staging_customer  (1000 rows)
-- -------------------------------------------------------------


-- -------------------------------------------------------------
-- staging_product  (50 rows)
-- -------------------------------------------------------------

-- Sanity check on staging load
SELECT 'staging_sales' AS tbl, COUNT(*) AS row_count FROM staging_sales
UNION ALL SELECT 'staging_customer', COUNT(*) FROM staging_customer
UNION ALL SELECT 'staging_product', COUNT(*) FROM staging_product;

-- =============================================================
-- Populate the Star Schema from Staging
-- =============================================================

SELECT DISTINCT Region FROM staging_customer;

SELECT sc.CustomerID, sc.FirstName, sc.LastName, sc.Gender, r.RegionID, sc.SSN
FROM staging_customer sc
JOIN dim_region r ON sc.Region = r.RegionName;

SELECT DISTINCT ProductID, ProductName, Category FROM staging_product;

SELECT SaleID, ProductID, CustomerID, SalesAmount, Quantity, `Timestamp` FROM staging_sales;

-- Final check
SELECT 'dim_region' AS tbl, COUNT(*) AS row_count FROM dim_region
UNION ALL SELECT 'dim_customer', COUNT(*) FROM dim_customer
UNION ALL SELECT 'dim_product', COUNT(*) FROM dim_product
UNION ALL SELECT 'fact_sales', COUNT(*) FROM fact_sales;